(()=>{(async function(){console.info("[nano.js KERNEL] seeding, and decryption pipeline...");try{let e=await fetch("./src/Gate.bundle.enc");if(!e.ok)throw new Error(`HTTP error! status: ${e.status}`);let t=await e.json();if(t.cipherProtocol!=="GFQM")throw new Error("Unsupported cipher protocol");let n=Uint8Array.from(atob(t.ciphertext),r=>r.charCodeAt(0)),a=window.client;a&&a.seed(n,{dht:!1,tracker:!1,pex:!0},r=>{console.info(`[nano.js KERNEL] PEX swarm anchored via client.seed: ${r.infoHash}`)});let i=Uint8Array.from(c(t.iv)),d=Uint8Array.from(c(t.secretKeyMock)),s=Uint8Array.from(c(t.authTag)),o=new Uint8Array(n.length+s.length);o.set(n),o.set(s,n.length);let p=await crypto.subtle.importKey("raw",d,{name:"AES-GCM"},!1,["decrypt"]),l=await crypto.subtle.decrypt({name:"AES-GCM",iv:i,tagLength:128},p,o),y=new TextDecoder().decode(l);new Function(y)(),console.info("[nano.js KERNEL SUCCESS] Gate.bundle.enc successfully compiled and executed.")}catch(e){console.error("[nano.js KERNEL ERROR]:",e)}})();function c(e){return e.match(/.{1,2}/g).map(t=>parseInt(t,16))}})();
